Ext._define('edocs.protocolo.SelectLocationWindow', {
    extend: 'core.RestfulWindow',

    rest: 'edocs.protocolo.ProtocoloRestful',

    width: 550,

    height: 100,

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                {
                    xtype: 'hidden',
                    name: 'pkset',
                    value: cfg.params.pkset
                },            
                this.getDepartmentField(cfg)
            ]
            });

        return this._formPanel;
    },

    getDepartmentField: function(cfg) {
        if(!this._departmentField){
            this._departmentField = Ext._create('core.fields.ComboField', {
                fieldLabel: 'Departamento',
                // hiddenName: this.nameField,
                hiddenName: 'departament',
                displayField: 'description',
                store: Ext._create('Ext.data.Store', {
                    proxy: Ext._create('Ext.data.HttpProxy', {
                        url: core.callAction('EDOCManage', 'work_locations')
                    }),
                    reader: Ext._create('Ext.data.JsonReader', {
                        totalProperty: 'count',
                        root: 'collection',
                        fields: [
                            {name: 'pk', type: 'int'},
                            {name: 'description', type: 'string'},
                        ]
                    })
                }),
                width: 395,
                allowBlank: false
            });
        }

        return this._departmentField;
    },

    save: function(){
        var form = this.getFormPanel().getForm();
        var pkset = form.getValues().pkset.split(',');

        Ext.Ajax.request({
            url: core.callAction('EDOCManage', 'sign_received'),
            params: {
                pkset: pkset,
                department: form.getValues().departament
            },
            scope: this,
            callback: function() {
                // mask.hide();
            },
            success: function(xhr) {
                var rst = Ext.decode(xhr.responseText);

                if(rst.success) {
                    this.resource.getStore().reload()
                    this.destroy();
                    // this.getStore().reload();
                    // if(this.otherInboxFn) this.otherInboxFn().getStore().reload();
                }
                else
                    Ext.Msg.show({
                        title: 'Assinando documentos',
                        msg: rst.message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
            },
            failure: function() {
                Ext.Msg.show({
                    title: 'Assinando documentos',
                    msg: 'Recurso indisponível no momento.',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            }
        });   
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(cfg, {
            title:'Selecione um departamento para receber o documento',
            'disableSaveAndNew': true,
        });

        edocs.protocolo.SelectLocationWindow.superclass.constructor.call(this, cfg);
    },
    
});

